// Writes app/code-theme.css: overrides for every github-light / github-dark token
// colour that is under 4.5:1 on the code background. Run: node scripts/code-theme.mjs
import fs from 'node:fs';
import { CODE_BG, codeColourReport } from './lib/code-colors.mjs';

const rows = await codeColourReport();
const fixes = rows.filter((r) => r.fixed !== r.colour);

const lines = [
  '/* Generated by scripts/code-theme.mjs. Do not edit by hand. */',
  `/* Code background: ${CODE_BG.light} (light) / ${CODE_BG.dark} (dark). Every token >= 4.6:1. */`,
  '',
];
for (const r of fixes) {
  const scope = r.mode === 'light' ? 'html:not(.dark)' : 'html.dark';
  const varName = r.mode === 'light' ? '--shiki-light' : '--shiki-dark';
  lines.push(
    `${scope} .shiki code span[style*="${varName}:${r.colour}" i] { color: ${r.fixed}; } /* ${r.before.toFixed(2)} -> ${r.after.toFixed(2)} */`
  );
}
fs.writeFileSync('app/code-theme.css', lines.join('\n') + '\n');
console.log(`Wrote ${fixes.length} code colour overrides to app/code-theme.css`);
